  for (int pin : rgb) {
    pinMode(pin, OUTPUT);
    digitalWrite(pin, commonAnode ? HIGH : LOW);
  }
}

void loop() {
  for (int pin : rgb) {
    digitalWrite(pin, commonAnode ? LOW : HIGH);
    delay(400);
